[TFMDocumentType(staticMethodStr(TFMConstants, Search))]
class TFMRequestSearchElement extends TFMRequestElement
{
    TFMRequestParametersElement     parms;
    TFMOrderTypes                   type;

}

Method.Source:
public TFMOrderTypes parmType(TFMOrderTypes _type = Type)
{
    type = _type;
    return type;
}

public TFMRequestParametersElement parmParameters(TFMRequestParametersElement _parms = parms)
{
    parms = _parms;
    if (!parms)
    {
        parms = new TFMRequestParametersElement();
    }
    return parms;
}
